create sequence application_seq start with 1 increment by 50;
create sequence branch_seq start with 1 increment by 50;
create sequence edge_seq start with 1 increment by 50;
create sequence node_seq start with 1 increment by 50;
create sequence page_seq start with 1 increment by 50;
create sequence ui_component_seq start with 1 increment by 50;
create sequence user_seq start with 1 increment by 50;
create sequence version_control_seq start with 1 increment by 50;
create sequence workflow_seq start with 1 increment by 50;
create table "application" (created_at timestamp(6) not null, id bigint not null, last_modified timestamp(6), description varchar(255) not null, title varchar(255) not null, primary key (id));
create table "branch" (application_id bigint not null, created_at timestamp(6) not null, created_by_id bigint not null, id bigint not null, last_modified timestamp(6), description varchar(255) not null, latest_version varchar(255), name varchar(255) not null, primary key (id));
create table "edge" (created_at timestamp(6) not null, id bigint not null, last_modified timestamp(6), source_node_id bigint not null, target_node_id bigint not null, source_port varchar(255) not null, primary key (id));
create table "node" (created_at timestamp(6) not null, id bigint not null, last_modified timestamp(6), workflow_id bigint not null, type varchar(255) not null, props jsonb not null, primary key (id));
create table "page" (branch_id bigint not null, created_at timestamp(6) not null, id bigint not null, last_modified timestamp(6), name varchar(255) not null, path varchar(255) not null, primary key (id));
create table "ui_component" (created_at timestamp(6) not null, id bigint not null, last_modified timestamp(6), page_id bigint not null, workflow_id bigint, type varchar(255) not null, props jsonb not null, primary key (id));
create table "user" (created_at timestamp(6) not null, id bigint not null, last_modified timestamp(6), email varchar(255) not null unique, first_name varchar(255) not null, last_name varchar(255) not null, password varchar(255) not null, username varchar(255) not null unique, primary key (id));
create table "version_control" (branch_id bigint not null, created_at timestamp(6) not null, id bigint not null, last_modified timestamp(6), modified_by_id bigint not null, version varchar(255), application_definition json not null, primary key (id), unique (version, branch_id));
create table "workflow" (branch_id bigint, created_at timestamp(6) not null, id bigint not null, last_modified timestamp(6), name varchar(255) not null, status varchar(255) not null check ((status in ('COMPLETED','ACTIVE','FAILED','DRAFT','RUNNING'))), primary key (id));
alter table if exists "branch" add constraint FK3ecj8c3ui097jp6oo422qav7c foreign key (application_id) references "application";
alter table if exists "branch" add constraint FKajjvtuj792u3sjwyiv2pxm24 foreign key (created_by_id) references "user";
alter table if exists "edge" add constraint FK6cwe12ocngcyxpxennwohwnfl foreign key (source_node_id) references "node";
alter table if exists "edge" add constraint FKcnmjexckol0ed8sglmq6fgd0e foreign key (target_node_id) references "node";
alter table if exists "node" add constraint FKkeprq4go94pqb95cno3x0t2y foreign key (workflow_id) references "workflow";
alter table if exists "page" add constraint FKovfpkikgwvbs2h4fsp0smalbe foreign key (branch_id) references "branch";
alter table if exists "ui_component" add constraint FKerhgi44pov98x3jtu9hogiie6 foreign key (page_id) references "page";
alter table if exists "ui_component" add constraint FKcw8fh4mv5pq1r7vt5hsjwcobg foreign key (workflow_id) references "workflow";
alter table if exists "version_control" add constraint FK99g6udp26dhjxoqgfia67vdd1 foreign key (branch_id) references "branch";
alter table if exists "version_control" add constraint FKbryx0u4lcnipvq1xoqc4yo9ug foreign key (modified_by_id) references "user";
alter table if exists "workflow" add constraint FKnsi7ivo97nf2e6pfm2yi461j4 foreign key (branch_id) references "branch";
